"use client";
import { useEffect, useId, useMemo, useState } from "react";
import useSWR from "swr";
import Link from "next/link";
import { ArrowRight, ArrowUpRight, ArrowUp, Boxes, Check, ChevronDown, Coins, Download, Edit3, Gift, Plus, RefreshCw, Search, ShieldCheck, SlidersHorizontal, Trash2, Wallet, X, CircleDollarSign, TrendingUp, ReceiptText, ScanLine } from "lucide-react";
import { api, waitTask, type Row } from "../lib/api";
import type { Actions } from "./Dashboard";
import { UpdateSettings } from "./Updates";
import ReadStatus from "./ReadStatus";
import ChromeDelivery from "./ChromeDelivery";
import BuyerMessageTemplates from "./BuyerMessageTemplates";
