import { Badge, Button, Dialog, Empty, External, Field, Notice, Panel, Sparkline, Spinner, State, Toggle, date, money } from "./ui";

const options = (items: Row[], label = "name") => items.map(i => <option key={i.id} value={i.id}>{i[label] || i.title || i.id}</option>);
const fetcher = (path: string) => api(path);
function useData(path: string) { return useSWR(path, fetcher, { refreshInterval: 5000 }); }
async function task(path: string, body?: unknown) { const r = await api(path, "POST", body); return r.task_id ? await waitTask(r.task_id) : r; }
function ErrorNotice({ error, cached = false }: { error: any; cached?: boolean }) { return <ReadStatus error={error} cached={cached} />; }
function Metric({ title, value, icon: Icon, detail, accent }: any) { return <article className={`metric ${accent ? "accent" : ""}`}><div className="metric-top"><span>{title}</span><Icon size={18} /></div><strong>{value}</strong><small>{detail}</small></article>; }

function PlayerokBalance() {
  const connections = useData("/connections");
  const connection = connections.data?.items?.find((c: Row) => c.id === "playerok");
  const balance = connection?.balance;
  const stale = !!connection?.last_success && (connection.status !== "CONNECTED" || Date.now() / 1000 - connection.last_success > 600);
  return <Panel title="Баланс Playerok" subtitle="Средства на площадке" action={stale ? <Badge tone="amber">Данные устарели</Badge> : undefined}>
    <ErrorNotice error={connections.error} cached={!!connections.data} />
    <div className="playerok-balance-grid">
      <div><small>Доступно</small><strong>{money(balance?.available)}</strong><span>Для вывода и оплаты премиума</span></div>
      <div><small>В заморозке</small><strong>{money(balance?.pendingIncome)}</strong><span>Ожидает зачисления в доступный баланс</span></div>
      <div><small>Всего на балансе</small><strong>{money(balance?.value)}</strong><span>Общая сумма по данным Playerok</span></div>
    </div>
    <div className="panel-note">{connection?.last_success ? `Обновлено: ${date(connection.last_success)}` : "Баланс появится после успешной проверки Playerok"}{connection?.last_error && <span className="red-text">Не удалось обновить. Показаны последние полученные данные.</span>}</div>
  </Panel>;
}

export function Overview({ act, busy }: Actions) {
  const [period, setPeriod] = useState("all");
  const start = useMemo(() => period === "all" ? "" : "?start=" + String(Math.floor(Date.now() / 1000) - Number(period) * 86400), [period]);
  const dashboard = useData("/dashboard" + start), quotes = useData("/quotes");
  const d = dashboard.data;
  const mrkt = d?.connections?.items.find((c: Row) => c.id === "mrkt");
  const chartPair = quotes.data?.items?.find((q: Row) => q.available)?.id;
  const values = (quotes.data?.history || []).filter((h: Row) => h.available && h.pair_id === chartPair).slice(0, 24).reverse().map((h: Row) => Number(h.ton));
  return <><PlayerokBalance /><div className="section-toolbar"><div className="button-group"><div className="section-caption"><span className="live-dot" />Живые данные вашего магазина</div><select aria-label="Период обзора" value={period} onChange={e => setPeriod(e.target.value)}><option value="all">Всё время</option><option value="1">24 часа</option><option value="7">Неделя</option><option value="30">Месяц</option></select></div><Button secondary disabled={busy} onClick={() => act(() => task("/connections/check", { name: "all" }), "Проверка подключений завершена")}><RefreshCw size={15} />Проверить подключения</Button></div><ErrorNotice error={dashboard.error} cached={!!dashboard.data} /><div className="overview-summary"><section className="wallet-card"><div className="wallet-card-head"><span>Кошельки магазина</span><Wallet size={18} /></div><div className="wallet-main"><small>Доступно на MRKT</small><strong>{money(mrkt?.mrkt_ton, "TON")}</strong><span>Для закупки NFT Gifts</span></div><div className="wallet-mini"><div><span className="wallet-token"><Gift size={16} /></span><div><small>Telegram Stars</small><strong>{mrkt?.stars ?? "—"} Stars</strong></div></div><div><span className="wallet-token ton"><TrendingUp size={16} /></span><div><small>Курс TON / RUB</small><strong>{money(d?.fx?.rate)}</strong></div></div></div><Link prefetch={false} href="/finance" className="btn">Открыть финансы <ArrowUpRight size={15} /></Link></section><div className="metrics"><Metric title="Выручка" value={money(d?.revenue_rub)} icon={CircleDollarSign} detail="По подтверждённым операциям" accent /><Metric title="Чистая прибыль" value={money(d?.profit_rub)} icon={TrendingUp} detail="После учтённых расходов" /><Metric title="Активные лоты" value={d?.active_lots ?? "—"} icon={Boxes} detail={`${d?.inactive_lots ?? 0} неактивных объявлений`} /><Metric title="Заказы" value={d?.orders ?? "—"} icon={ReceiptText} detail={`${d?.problem_orders ?? 0} требуют внимания`} /></div></div><div className="overview-grid"><Panel title="Закупочные цены" subtitle="Изменение минимальной цены на MRKT, TON" action={<Link prefetch={false} className="text-link" href="/gifts">Все подарки <ArrowUpRight size={15} /></Link>}><div className="chart-summary"><strong>{quotes.data?.items?.find((q: Row) => q.available)?.ton ? money(quotes.data.items.find((q: Row) => q.available).ton, "TON") : "—"}</strong><span>Последние проверки одной модели</span></div><Sparkline values={values} /><div className="chart-footer"><span>{d?.quote_count ?? 0} комбинаций в мониторинге</span><span>TON/RUB: {money(d?.fx?.rate)}</span></div></Panel><Panel title="Подключения" subtitle="Состояние внешних сервисов" action={<span className="live-dot" />}><div className="connection-list">{(d?.connections?.items || []).map((c: Row) => <div key={c.id} className="connection-row"><span className={`connection-icon ${c.id}`}>{c.id === "mrkt" ? <Coins size={19} /> : c.id === "telegram" ? <ArrowUpRight size={19} /> : <Boxes size={19} />}</span><div><strong>{c.id === "mrkt" ? "MRKT" : c.id === "telegram" ? "Telegram" : "Playerok"}</strong><small title={c.last_error}>{c.last_error || date(c.last_success)}</small></div><State value={c.status} /></div>)}</div><div className="balance-strip"><div><small>MRKT</small><strong>{money(mrkt?.mrkt_ton, "TON")}</strong></div><div><small>Telegram Stars</small><strong>{mrkt?.stars ?? "—"} <span>✦</span></strong></div></div></Panel></div><div className="overview-bottom"><Panel title="Последние действия" subtitle="Что происходит в вашем магазине" action={<Link prefetch={false} className="text-link" href="/history">Вся история <ArrowRight size={15} /></Link>}>{d?.events?.length ? <div className="events-list">{d.events.slice(0, 6).map((e: Row) => <div className="event-item" key={e.id}><span className={`event-symbol ${e.level === "ERROR" ? "error" : ""}`}>{e.level === "ERROR" ? "!" : <Check size={13} />}</span><div><strong>{e.title}</strong><small>{e.detail || e.action}</small></div><time>{date(e.updated_at)}</time></div>)}</div> : <Empty text="Здесь будет история магазина" />}</Panel></div></>;
}

function OperationConfirm({ operation, onClose, act, busy }: Actions & { operation: Row; onClose: () => void }) {
  const settings = useData("/settings"), e = operation.expected || {}, p = operation.payload || {};
  const list = operation.operations || [operation];
  return <Dialog title={operation.action === "promotion" ? "Поднять активный лот" : operation.action === "price" ? "Применить рассчитанную цену" : "Подтвердить изменения"} onClose={onClose} busy={busy} footer={<><Button secondary onClick={onClose} disabled={busy}>Закрыть</Button><Button disabled={busy || settings.data?.emergency_stop || (operation.action === "promotion" && !settings.data?.promotions_enabled) || (operation.action === "price" && !settings.data?.repricing_enabled) || operation.state === "EXPIRED"} onClick={() => act(async () => { for (const op of list) await api("/operations/execute", "POST", { operation_id: op.id }); onClose(); }, "Операция поставлена в очередь")} >{busy && <Spinner />}Подтвердить</Button></>}><div className="summary-grid">{operation.action === "promotion" ? <><div><small>Стоимость поднятия</small><strong>{money(e.cost_rub)}</strong></div><div><small>Баланс Playerok</small><strong>{money(e.balance)}</strong></div></> : operation.action === "price" ? <><div><small>Новая цена</small><strong>{money(p.price)}</strong></div><div><small>Ожидаемая прибыль</small><strong>{money(e.profit_rub)}</strong></div><div><small>Закупка</small><strong>{money(e.purchase_rub)}</strong></div><div><small>Передача</small><strong>{money(e.transfer_rub)}</strong></div><div><small>Премиум в цене продажи</small><strong>{money(e.promotion_rub ?? 0)}</strong><small>{e.premium_included ? `${e.premium_count} поднят. × ${money(e.premium_unit_rub)}` : "Не резервируется"}</small></div><div><small>Комиссии</small><strong>{money(e.fees_rub)}</strong></div><div><small>Курс TON</small><strong>{money(e.ton_rub)}</strong></div></> : <div><small>Подготовлено операций</small><strong>{list.length}</strong></div>}</div>{operation.action === "update" && <div className="change-list">{Object.entries(p.changes || {}).map(([k, v]) => <p key={k}><small>{{ name: "Название", description: "Описание", price: "Цена" }[k] || k}</small><span>{String(v)}</span></p>)}</div>}<p className="muted">Расчёт действует две минуты. Перед выполнением система повторно проверит условия.</p>{settings.data?.emergency_stop && <Notice error>Включена аварийная остановка.</Notice>}</Dialog>;
}

function ResolutionDialog({ operation, onClose, act, busy }: Actions & { operation: Row; onClose: () => void }) {
  const [resolution, setResolution] = useState("NOT_EXECUTED"), [evidence, setEvidence] = useState("");
  return <Dialog title="Ручная сверка списания" onClose={onClose} busy={busy} footer={<Button disabled={busy || evidence.trim().length < 10} onClick={() => act(async () => { await task(`/operations/${operation.id}/resolve`, { resolution, evidence }); onClose(); }, "Результат ручной сверки сохранён")}>Зафиксировать результат</Button>}><Notice>Сначала проверьте историю платежей Playerok. Это действие только фиксирует результат и не повторяет оплату.</Notice><Field label="Что произошло"><select value={resolution} onChange={e => setResolution(e.target.value)}><option value="NOT_EXECUTED">Списания не было</option><option value="CONFIRMED">Премиум оплачен, списание подтверждено</option></select></Field><Field label="Результат проверки"><textarea rows={4} value={evidence} onChange={e => setEvidence(e.target.value)} placeholder="Дата, сумма и сведения из истории площадки" /></Field></Dialog>;
}

export function Lots({ act, busy }: Actions) {
  const lots = useData("/lots"), pairs = useData("/gift-pairs"), profiles = useData("/fee-profiles"), capabilities = useData("/lots/capabilities");
  const [search, setSearch] = useState(""), [tab, setTab] = useState("active"), [selected, setSelected] = useState<string[]>([]);
  const [binding, setBinding] = useState<Row | null>(null), [pairId, setPairId] = useState(""), [feeId, setFeeId] = useState("default");
  const [deliveryMode, setDeliveryMode] = useState("manual");
  const [editing, setEditing] = useState<Row | null>(null), [changes, setChanges] = useState({ name: "", price: "", description: "" });
  const [bulk, setBulk] = useState(false), [bulkText, setBulkText] = useState("");
  const [preview, setPreview] = useState<Row | null>(null), [creating, setCreating] = useState(false);
  const [calculating, setCalculating] = useState<string | null>(null), [calculationError, setCalculationError] = useState("");
  async function calculatePrice(lot: Row) {
    setCalculationError("");
    if (!lot.pair_id) { setCalculationError("Сначала привяжите коллекцию и модель к этому лоту."); setBinding(lot); setDeliveryMode("manual"); setPairId(""); setFeeId(lot.fee_profile_id || "default"); return; }
    setCalculating(lot.id);
    try { setPreview(await task(`/pricing/${lot.id}/preview`)); }
    catch (e) { setCalculationError((e as Error).message); }
    finally { setCalculating(null); }
  }
  const records = (lots.data?.items || []).filter((l: Row) => tab === "active" ? l.status === "APPROVED" && !l.missing : l.status !== "APPROVED" || l.missing).filter((l: Row) => `${l.title} ${l.pair?.collection} ${l.pair?.model}`.toLowerCase().includes(search.toLowerCase()));
  return <><div className="section-toolbar"><div className="tabs"><button className={tab === "active" ? "active" : ""} onClick={() => setTab("active")}>Активные</button><button className={tab === "other" ? "active" : ""} onClick={() => setTab("other")}>Остальные</button></div><div className="button-group"><Button secondary disabled={busy} onClick={() => act(() => task("/lots/sync"), "Лоты обновлены")}><RefreshCw size={15} />Синхронизация</Button><Button onClick={() => setCreating(true)}><Plus size={16} />Новый лот</Button></div></div><ErrorNotice error={lots.error} cached={!!lots.data} />{calculationError && <div role="alert" className="calculation-error"><Notice error>{calculationError}{/комисси/i.test(calculationError) && <Link prefetch={false} href="/fees" className="text-link">Открыть комиссии <ArrowRight size={14} /></Link>}{/Stars/i.test(calculationError) && <Link prefetch={false} href="/settings" className="text-link">Открыть настройки <ArrowRight size={14} /></Link>}</Notice></div>}<Panel><div className="table-toolbar"><label className="search-box"><Search size={16} /><input placeholder="Название, коллекция или модель" value={search} onChange={e => setSearch(e.target.value)} /></label><Button secondary disabled={!selected.length} onClick={() => setBulk(true)}>Описание · {selected.length}</Button></div>{lots.isLoading ? <div className="loading"><Spinner />Загрузка объявлений</div> : records.length ? <div className="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Выбрать все лоты" checked={records.length > 0 && records.every((r: Row) => selected.includes(r.id))} onChange={e => setSelected(e.target.checked ? records.map((r: Row) => r.id) : [])} /></th><th>Объявление</th><th>Тип товара / модель</th><th>Цена</th><th>Расчёт</th><th>Статус</th><th /></tr></thead><tbody>{records.map((l: Row) => <tr key={l.id}><td><input type="checkbox" aria-label={`Выбрать ${l.title}`} checked={selected.includes(l.id)} onChange={e => setSelected(e.target.checked ? [...selected, l.id] : selected.filter(id => id !== l.id))} /></td><td><div className="item-cell"><div className="item-image">{l.image ? <img src={l.image} alt="" /> : <Gift size={21} />}</div><div><strong>{l.title}</strong><small>{l.id.slice(-12)}</small></div></div></td><td><button className="binding-button" onClick={() => { setBinding(l); setDeliveryMode(l.delivery_mode || (l.pair_id ? "telegram_nft" : "manual")); setPairId(l.pair_id || ""); setFeeId(l.fee_profile_id || "default"); }}>{l.pair ? <><strong>{l.pair.collection}</strong><small>{l.pair.model}</small></> : <><strong>Обычный товар</strong><small>Без автовыдачи · настроить</small></>}</button></td><td><strong>{money(l.price)}</strong>{l.premium && <small className="premium-label">✦ Премиум</small>}</td><td>{(!l.pair_id || l.delivery_mode === "manual") ? <span className="muted">Не применяется</span> : l.estimate?.status === "READY" ? <><strong className="green-text">{money(l.estimate.sale_price)}</strong><small>Прибыль {money(l.estimate.profit_rub)} · премиум {money(l.estimate.promotion_rub ?? 0)}</small>{l.estimate.current_profit_rub != null && <small className={Number(l.estimate.current_profit_rub) < 0 ? "red-text" : "muted"}>При текущей цене: {money(l.estimate.current_profit_rub)}</small>}</> : <span className="muted" title={l.estimate?.error}>{l.estimate?.error ? "Нужна настройка" : "—"}</span>}</td><td><State value={l.status} /></td><td><div className="row-actions">{l.url && <External href={l.url} />}<button className="icon-button" title="Редактировать" aria-label={`Редактировать ${l.title}`} disabled={busy} onClick={() => act(async () => { await task(`/lots/${l.id}/refresh`); const row = await api(`/lots/${l.id}`); setEditing(row); setChanges({ name: row.title, price: String(row.price || ""), description: row.description || "" }); }, "Описание лота загружено")}><Edit3 size={16} /></button>{l.status === "APPROVED" && <>{l.pair_id && l.delivery_mode !== "manual" && <button className="icon-button price-preview-button" title="Предварительный расчёт цены" aria-label={`Рассчитать цену ${l.title}`} disabled={busy || calculating !== null} aria-busy={calculating === l.id} onClick={() => calculatePrice(l)}>{calculating === l.id ? <Spinner /> : <SlidersHorizontal size={16} />}<span className="action-label">{calculating === l.id ? "Считаем…" : "Расчёт"}</span></button>}<button className="icon-button highlight" title="Поднять через премиум" aria-label={`Поднять ${l.title}`} disabled={busy} onClick={() => act(async () => setPreview(await task(`/promotions/${l.id}/preview`)), "Стоимость поднятия получена")}><ArrowUp size={17} /></button></>}</div></td></tr>)}</tbody></table></div> : <Empty text="Объявления не найдены" detail="Нажмите «Синхронизация» или измените фильтр." />}<div className="table-footer"><span>{records.length} объявлений</span><span>Обновление данных каждые 5 секунд</span></div></Panel><p className="muted footnote">{capabilities.data?.manual_reason}</p>{binding && <Dialog title="Тип товара и выдача" onClose={() => setBinding(null)} footer={<Button disabled={(deliveryMode === "telegram_nft" && !pairId) || busy} onClick={() => act(async () => { await api(`/lots/${binding.id}/binding`, "PATCH", { delivery_mode: deliveryMode, pair_id: deliveryMode === "telegram_nft" ? pairId : null, fee_profile_id: feeId }); setBinding(null); })}>Сохранить</Button>}><p>{binding.title}</p><Field label="Тип товара"><select value={deliveryMode} onChange={e => setDeliveryMode(e.target.value)}><option value="manual">Обычный товар — без автовыдачи</option><option value="telegram_nft">Telegram NFT — закупка на MRKT и выдача</option></select></Field><Notice>{deliveryMode === "manual" ? "Закупки на MRKT и автоматической выдачи не будет. Редактирование, синхронизация и поднятия доступны." : "Выдаётся только выбранная коллекция и модель. Дополнительно нужны общие разрешения на закупку и передачу."}</Notice>{deliveryMode === "telegram_nft" && <><GiftPairPicker value={pairId} onChange={setPairId} busy={busy} /><Field label="Профиль комиссий"><select value={feeId} onChange={e => setFeeId(e.target.value)}>{options(profiles.data?.items || [])}</select></Field></>}</Dialog>}{editing && <Dialog title="Редактировать объявление" busy={busy} onClose={() => setEditing(null)} footer={<Button disabled={busy} onClick={() => act(async () => { const op = await api(`/lots/${editing.id}/edit-preview`, "POST", { name: changes.name, price: Number(changes.price), description: changes.description }); setEditing(null); setPreview(op); }, "Изменения подготовлены")} >Проверить изменения</Button>}><Field label="Название"><input value={changes.name} onChange={e => setChanges({ ...changes, name: e.target.value })} /></Field><Field label="Цена, ₽"><input type="number" min={1} value={changes.price} onChange={e => setChanges({ ...changes, price: e.target.value })} /></Field><Field label="Описание"><textarea rows={9} value={changes.description} onChange={e => setChanges({ ...changes, description: e.target.value })} /></Field></Dialog>}{bulk && <Dialog title={`Описание для ${selected.length} лотов`} onClose={() => setBulk(false)} footer={<Button disabled={busy} onClick={() => act(async () => { const r = await api("/lots/bulk-preview", "POST", { item_ids: selected, changes: { description: bulkText } }); setBulk(false); setPreview({ id: "bulk", operations: r.items, state: "PREVIEW" }); }, "Массовое изменение подготовлено")} >Предварительный просмотр</Button>}><Field label="Новое описание"><textarea rows={9} value={bulkText} onChange={e => setBulkText(e.target.value)} /></Field><Notice>Описание выбранных лотов будет полностью заменено после подтверждения.</Notice></Dialog>}{creating && <CreateLot act={act} busy={busy} onClose={() => setCreating(false)} onPreview={setPreview} />}{preview && <OperationConfirm operation={preview} onClose={() => setPreview(null)} act={act} busy={busy} />}</>;
}

function GiftPairPicker({ value, onChange, busy }: { value: string; onChange: (id: string, pair?: Row) => void; busy: boolean }) {
  const pairs = useData("/gift-pairs");
  const [expanded, setExpanded] = useState(false), [saving, setSaving] = useState(false), [loadingModels, setLoadingModels] = useState(false);
  const [collection, setCollection] = useState(""), [model, setModel] = useState(""), [error, setError] = useState("");
  const [created, setCreated] = useState<Row[]>([]);
  const id = useId();
  const models = useSWR(expanded && collection.trim() ? "/gift-pairs/models?collection=" + encodeURIComponent(collection.trim()) : null, fetcher);
  const items = [...(pairs.data?.items || []), ...created.filter(p => !(pairs.data?.items || []).some((r: Row) => r.id === p.id))];
  const pending = busy || saving || loadingModels;
  async function savePair() {
    setSaving(true); setError("");
    try {
      const pair = await api<Row>("/gift-pairs", "POST", { collection: collection.trim(), model: model.trim() });
      setCreated(rows => [...rows.filter(p => p.id !== pair.id), pair]);
      onChange(pair.id, pair); setExpanded(false); setCollection(""); setModel("");
      void pairs.mutate().catch(() => {});
    } catch (e) { setError((e as Error).message); }
    finally { setSaving(false); }
  }
  return <div className="gift-pair-picker">
    <Field label="Коллекция — модель"><select value={value} disabled={pending} onChange={e => onChange(e.target.value)}><option value="">Выберите точную пару</option>{items.map((p: Row) => <option key={p.id} value={p.id}>{p.collection} — {p.model}</option>)}</select></Field>
    {!expanded ? <button type="button" className="text-link" disabled={pending} onClick={() => { setExpanded(true); setError(""); }}><Plus size={15} />Создать новую пару</button> : <section className="inline-pair-form" aria-label="Создание пары">
      <div className="inline-pair-heading"><strong>Новая коллекция и модель</strong><button type="button" className="icon-button" aria-label="Отменить создание пары" disabled={pending} onClick={() => setExpanded(false)}><X size={17} /></button></div>
      <Field label="Название коллекции"><input list={id + "-collections"} placeholder="Например, Liberty Figure" disabled={pending} value={collection} onChange={e => { setCollection(e.target.value); setModel(""); }} /><datalist id={id + "-collections"}>{(pairs.data?.catalog || []).map((c: Row) => <option key={c.id} value={c.name} />)}</datalist></Field>
      <div className="inline-label"><span>Модели выбранной коллекции</span><button type="button" className="text-link" disabled={pending || !collection.trim()} onClick={async () => { setLoadingModels(true); setError(""); try { await task("/gift-pairs/models", { collection: collection.trim() }); await models.mutate(); } catch (e) { setError((e as Error).message); } finally { setLoadingModels(false); } }}>{loadingModels ? <Spinner /> : <RefreshCw size={13} />}Загрузить из MRKT</button></div>
      <Field label="Модель"><input list={id + "-models"} placeholder="Например, Obsidian" disabled={pending} value={model} onChange={e => setModel(e.target.value)} /><datalist id={id + "-models"}>{(models.data?.items || []).map((m: Row, i: number) => <option key={m.id || i} value={m.name || m.modelName} />)}</datalist></Field>
      {error && <div role="alert"><Notice error>{error}</Notice></div>}
      <div className="button-group"><Button disabled={pending || !collection.trim() || !model.trim()} onClick={savePair}>{saving ? <Spinner /> : <Plus size={15} />}Создать и выбрать</Button><Button secondary disabled={pending} onClick={() => setExpanded(false)}>Отмена</Button></div>
      <small>Пара будет выбрана в этом окне. Покупок и изменений на Playerok не произойдёт.</small>
    </section>}
  </div>;
}

function CreateLot({ act, busy, onClose, onPreview }: Actions & { onClose: () => void; onPreview: (op: Row) => void }) {
  const pairs = useData("/gift-pairs"), settings = useData("/settings");
  const [pairId, setPairId] = useState(""), [createdPair, setCreatedPair] = useState<Row | null>(null);
  const selectedPair = pairs.data?.items?.find((p: Row) => p.id === pairId) || (createdPair?.id === pairId ? createdPair : null);
  const collection = selectedPair?.collection || "";
  const [title, setTitle] = useState(""), [price, setPrice] = useState(""), [description, setDescription] = useState(""), [image, setImage] = useState<File | null>(null);
  useEffect(() => { if (settings.data) setDescription(settings.data.description_template || ""); }, [settings.data]);
  return <Dialog title="Новое объявление" busy={busy} onClose={onClose} footer={<Button disabled={busy || !title || !collection || !image || !Number(price)} onClick={() => act(async () => { const data = new FormData(); data.set("title", title); data.set("collection", collection); data.set("pair_id", pairId); data.set("price", price); data.set("description", description); data.set("image", image!); const op = await api("/lots/create-preview", "POST", data); onClose(); onPreview(op); }, "Объявление подготовлено")} >Подготовить объявление</Button>}><Field label="Название"><input value={title} onChange={e => setTitle(e.target.value)} /></Field><GiftPairPicker value={pairId} onChange={(id, pair) => { setPairId(id); setCreatedPair(pair || null); }} busy={busy} /><Field label="Цена, ₽"><input type="number" min={1} value={price} onChange={e => setPrice(e.target.value)} /></Field><Field label="Изображение"><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e => setImage(e.target.files?.[0] || null)} /></Field><Field label="Описание"><textarea rows={7} value={description} onChange={e => setDescription(e.target.value)} /></Field></Dialog>;
}

export function Gifts({ act, busy }: Actions) {
  const pairs = useData("/gift-pairs"), quotes = useData("/quotes");
  const [collection, setCollection] = useState(""), [model, setModel] = useState("");
  const [modelTask, setModelTask] = useState(false);
  const models = useSWR(collection ? "/gift-pairs/models?collection=" + encodeURIComponent(collection) : null, fetcher);
  const q = new Map<string, Row>((quotes.data?.items || []).map((q: Row) => [q.id, q]));
  return <><div className="two-columns"><Panel title="Коллекция и модель" subtitle="Добавьте сочетание для поиска цены на MRKT и привязки к лоту"><div className="form-pad"><Field label="Название коллекции"><input list="collections" placeholder="Например, Liberty Figure" value={collection} onChange={e => { setCollection(e.target.value); setModel(""); }} /><datalist id="collections">{(pairs.data?.catalog || []).map((c: Row) => <option key={c.id} value={c.name} />)}</datalist></Field><div className="inline-label"><span>Доступные модели</span><button className="text-link" disabled={!collection || busy || modelTask} onClick={async () => { setModelTask(true); await act(async () => { await task("/gift-pairs/models", { collection }); await models.mutate(); }, "Модели загружены"); setModelTask(false); }}>{modelTask ? <Spinner /> : <RefreshCw size={13} />}Загрузить из MRKT</button></div><Field label="Модель"><input list="models" value={model} placeholder="Например, Obsidian" onChange={e => setModel(e.target.value)} /><datalist id="models">{(models.data?.items || []).map((m: Row, i: number) => <option key={m.id || i} value={m.name || m.modelName} />)}</datalist></Field><Button disabled={busy || !collection.trim() || !model.trim()} onClick={() => act(async () => { await api("/gift-pairs", "POST", { collection, model }); setModel(""); }, "Пара добавлена; проверка предложений поставлена в очередь")}><Plus size={16} />Добавить пару</Button></div></Panel><Panel title="Каталог MRKT" subtitle="Один источник для всех ваших объявлений"><div className="catalog-card"><Gift size={40} strokeWidth={1} /><strong>{pairs.data?.catalog?.length || 0}</strong><p>коллекций в локальном каталоге</p><Button secondary disabled={busy} onClick={() => act(() => task("/gift-pairs/catalog"), "Каталог обновлён")}><RefreshCw size={15} />Обновить каталог</Button><small>Фон, символ и номер не ограничивают выбор NFT.</small></div></Panel></div><Panel title="Пары в мониторинге" subtitle="Минимальная доступная цена для точного сочетания коллекции и модели">{pairs.data?.items?.length ? <div className="table-scroll"><table><thead><tr><th>Коллекция</th><th>Модель</th><th>Цена MRKT</th><th>Проверка</th><th /></tr></thead><tbody>{pairs.data.items.map((p: Row) => { const quote = q.get(p.id); return <tr key={p.id}><td><strong>{p.collection}</strong></td><td>{p.model}</td><td>{quote?.available ? <><strong>{money(quote.ton, "TON")}</strong><small>{quote.offers_in_page} предложений на странице</small></> : <span className="muted">{quote ? "Модель недоступна" : "Ожидает проверки"}</span>}</td><td>{date(quote?.fetched_at)}{quote?.last_error && <small className="red-text">{quote.last_error}</small>}</td><td><Button secondary disabled={busy} onClick={() => act(() => task("/quotes/refresh", { pair_id: p.id }), "Цена обновлена")}><RefreshCw size={14} />Проверить</Button></td></tr>; })}</tbody></table></div> : <Empty text="Добавьте первую пару" />}</Panel></>;
}

export function Fees({ act, busy }: Actions) {
  const data = useData("/fee-profiles");
  const [profileId, setProfileId] = useState("default"), [draft, setDraft] = useState<any>(null);
  useEffect(() => { const profile = data.data?.items?.find((p: Row) => p.id === profileId); if (profile && !draft) setDraft({ name: profile.name, configured: profile.configured, fees: profile.fees }); }, [data.data, profileId, draft]);
  const patchFee = (index: number, field: string, value: unknown) => setDraft({ ...draft, fees: draft.fees.map((f: any, i: number) => i === index ? { ...f, [field]: value } : f) });
  return <><div className="section-toolbar"><div className="button-group"><select value={profileId} onChange={e => { setProfileId(e.target.value); setDraft(null); }}>{options(data.data?.items || [])}</select><Button secondary onClick={() => { setProfileId(crypto.randomUUID()); setDraft({ name: "Новый профиль", configured: false, fees: [] }); }}><Plus size={15} />Профиль</Button></div><Button disabled={!draft || busy} onClick={() => act(() => api(`/fee-profiles/${profileId}`, "PUT", draft), "Профиль комиссий сохранён")}>Сохранить профиль</Button></div>{draft && <><Panel title="Профиль комиссий" subtitle="Применяется ко всем лотам, которые используют этот профиль"><div className="form-pad"><Field label="Название профиля"><input value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })} /></Field><Toggle label="Комиссии проверены и настроены" description="Без этого подтверждения автоматическое ценообразование не применяется." checked={draft.configured} onChange={v => setDraft({ ...draft, configured: v })} /></div></Panel><Panel title="Порядок удержаний" subtitle="Комиссии применяются сверху вниз" action={<Button secondary onClick={() => setDraft({ ...draft, fees: [...draft.fees, { name: "Новая комиссия", type: "percent", value: "0", basis: "remaining", include_fixed: false, enabled: true }] })}><Plus size={15} />Комиссия</Button>}>{draft.fees.length ? <div className="fee-list">{draft.fees.map((f: any, index: number) => <div className="fee-card" key={index}><span className="fee-number">{String(index + 1).padStart(2, "0")}</span><div className="fee-fields"><div className="form-grid"><Field label="Название"><input value={f.name} onChange={e => patchFee(index, "name", e.target.value)} /></Field><Field label="Тип"><select value={f.type} onChange={e => patchFee(index, "type", e.target.value)}><option value="percent">Процент</option><option value="fixed">Фиксированная сумма</option></select></Field><Field label={f.type === "fixed" ? "Сумма, ₽" : "Процент, %"}><input type="number" min={0} step="0.01" value={f.value} onChange={e => patchFee(index, "value", e.target.value)} /></Field>{f.type === "percent" && <Field label="База расчёта"><select value={f.basis} onChange={e => patchFee(index, "basis", e.target.value)}><option value="remaining">Остаток после предыдущих</option><option value="sale">Цена продажи</option><option value="purchase">Закупочная стоимость</option></select></Field>}</div><div className="fee-toggles"><label><input type="checkbox" checked={f.enabled} onChange={e => patchFee(index, "enabled", e.target.checked)} />Учитывать</label>{f.type === "percent" && <label><input type="checkbox" checked={f.include_fixed} onChange={e => patchFee(index, "include_fixed", e.target.checked)} />Учитывать фиксированные удержания в базе</label>}</div></div><div className="fee-actions"><button className="icon-button" title="Выше" disabled={!index} onClick={() => { const fees = [...draft.fees]; [fees[index - 1], fees[index]] = [fees[index], fees[index - 1]]; setDraft({ ...draft, fees }); }}><ArrowUp size={16} /></button><button className="icon-button" title="Удалить комиссию" onClick={() => setDraft({ ...draft, fees: draft.fees.filter((_: any, i: number) => i !== index) })}><Trash2 size={16} /></button></div></div>)}</div> : <Empty text="Добавьте комиссии" detail="Можно сохранить пустой профиль, если вы осознанно не учитываете удержания." />}</Panel></>}</>;
}

const defaultStrategy = { enabled: false, premium_mode: "auto", premium_purchases_per_sale: 1, profit_type: "percent", profit_value: "5", profit_basis: "purchase", min_price: 0, max_price: null, round_step: 1, change_threshold: 1, use_competitor: false, competitor_mode: "cheaper", competitor_offset: "1", competitor_offset_type: "rub", competitor_id: null };
export function Pricing({ act, busy }: Actions) {
  const data = useData("/pricing"), lots = useData("/lots"), competitors = useData("/competitors");
  const [draft, setDraft] = useState<any>(null), [target, setTarget] = useState("default"), [preview, setPreview] = useState<Row | null>(null);
  useEffect(() => { if (!draft && data.data) { const existing = target === "default" ? data.data.strategy : lots.data?.items?.find((l: Row) => l.id === target)?.strategy; const clean = { ...defaultStrategy, ...data.data.strategy, ...existing }; delete (clean as any).id; delete (clean as any).updated_at; setDraft(clean); } }, [data.data, lots.data, draft, target]);
  const update = (key: string, value: unknown) => setDraft({ ...draft, [key]: value });
  return <><div className="section-toolbar"><select value={target} onChange={e => { setTarget(e.target.value); setDraft(null); }}><option value="default">Общая стратегия</option>{options(lots.data?.items || [], "title")}</select><Button disabled={busy || !draft} onClick={() => act(async () => { if (target === "default") return api("/pricing/strategy", "PUT", draft); const lot = lots.data.items.find((l: Row) => l.id === target); if (!lot.pair_id) throw new Error("Сначала привяжите модель в разделе лотов"); return api(`/lots/${target}/binding`, "PATCH", { pair_id: lot.pair_id, fee_profile_id: lot.fee_profile_id || "default", strategy: draft }); }, "Стратегия сохранена")}>Сохранить стратегию</Button></div>{draft && <div className="two-columns"><Panel title="Целевая прибыль" subtitle="Система не снижает цену ниже безопасной"><div className="form-pad"><Toggle label="Применять эту стратегию автоматически" checked={draft.enabled} onChange={v => update("enabled", v)} description="Дополнительно требуется включить автоцены в настройках." /><Field label="Премиум в себестоимости" help="Авто: учитывать, если у лота премиум-статус или включено расписание поднятий."><select value={draft.premium_mode} onChange={e => update("premium_mode", e.target.value)}><option value="auto">По статусу лота и расписанию</option><option value="include">Всегда учитывать</option><option value="exclude">Не резервировать</option></select></Field><Field label="Поднятий на одну продажу" help="Плановое число оплат премиума на одну продажу. Тариф запрашивается для рассчитанной цены лота."><input type="number" min={1} max={100} disabled={draft.premium_mode === "exclude"} value={draft.premium_purchases_per_sale} onChange={e => update("premium_purchases_per_sale", Number(e.target.value))} /></Field><p className="muted footnote">Премиум учитывается отдельно от комиссий. Если добавляли его вручную в профиль комиссий, уберите ту строку, чтобы не учитывать дважды.</p><div className="form-grid"><Field label="Размер прибыли"><input type="number" min={0} step="0.01" value={draft.profit_value} onChange={e => update("profit_value", e.target.value)} /></Field><Field label="Единица"><select value={draft.profit_type} onChange={e => update("profit_type", e.target.value)}><option value="percent">Проценты</option><option value="rub">Рубли</option></select></Field><Field label="База прибыли"><select value={draft.profit_basis} onChange={e => update("profit_basis", e.target.value)}><option value="purchase">Закупочная стоимость NFT</option><option value="sale">Выручка</option></select></Field><Field label="Округление вверх, ₽"><input type="number" min={1} value={draft.round_step} onChange={e => update("round_step", Number(e.target.value))} /></Field><Field label="Минимальная цена, ₽"><input type="number" min={0} value={draft.min_price} onChange={e => update("min_price", Number(e.target.value))} /></Field><Field label="Максимальная цена, ₽"><input type="number" min={1} placeholder="Без ограничения" value={draft.max_price ?? ""} onChange={e => update("max_price", e.target.value ? Number(e.target.value) : null)} /></Field><Field label="Порог изменения, ₽"><input type="number" min={1} value={draft.change_threshold} onChange={e => update("change_threshold", Number(e.target.value))} /></Field></div></div></Panel><Panel title="Реакция на конкурентов" subtitle="Конкурентная цена ограничена безопасной снизу"><div className="form-pad"><Toggle label="Учитывать цены конкурентов" checked={draft.use_competitor} onChange={v => update("use_competitor", v)} /><Field label="Источник конкурентной цены"><select value={draft.competitor_id || ""} onChange={e => update("competitor_id", e.target.value || null)}><option value="">Минимальная среди подходящих</option>{options((competitors.data?.items || []).filter((c: Row) => target === "default" || c.lot_id === target), "title")}</select></Field><Field label="Режим"><select value={draft.competitor_mode} onChange={e => update("competitor_mode", e.target.value)}><option value="cheaper">Дешевле конкурента</option><option value="equal">Та же цена</option><option value="higher">Дороже конкурента</option></select></Field><div className="form-grid"><Field label="Отклонение"><input type="number" min={0} step="0.01" value={draft.competitor_offset} onChange={e => update("competitor_offset", e.target.value)} /></Field><Field label="Единица отклонения"><select value={draft.competitor_offset_type} onChange={e => update("competitor_offset_type", e.target.value)}><option value="rub">Рубли</option><option value="percent">Проценты</option></select></Field></div><Notice>Если предложения конкурентов устарели или не соответствуют модели, они исключаются из расчёта.</Notice></div></Panel></div>}<Panel title="Расчёты по лотам" subtitle="Закупка, комиссии, передача, премиум и прибыль">{data.data?.items?.length ? <div className="table-scroll"><table><thead><tr><th>Объявление</th><th>Закупка</th><th>Передача</th><th>Премиум</th><th>Цена продажи</th><th>Прибыль</th><th>При текущей цене</th><th /></tr></thead><tbody>{data.data.items.map((e: Row) => <tr key={e.id}><td><strong>{lots.data?.items?.find((l: Row) => l.id === e.id)?.title || e.id.slice(-12)}</strong>{e.error && <small className="red-text">{e.error}</small>}</td><td>{e.status === "READY" ? money(e.purchase_rub) : "—"}</td><td>{e.status === "READY" ? money(e.transfer_rub) : "—"}</td><td>{e.status === "READY" ? money(e.promotion_rub ?? 0) : "—"}</td><td>{e.status === "READY" ? money(e.sale_price) : <State value={e.status} />}</td><td className="green-text">{e.status === "READY" ? money(e.profit_rub) : "—"}</td><td className={Number(e.current_profit_rub) < 0 ? "red-text" : "muted"}>{e.status === "READY" ? money(e.current_profit_rub) : "—"}</td><td><Button secondary disabled={busy} onClick={() => act(async () => setPreview(await task(`/pricing/${e.id}/preview`)), "Цена рассчитана")}>Расчёт</Button></td></tr>)}</tbody></table></div> : <Empty text="Нет рассчитанных цен" detail="Привяжите модель к лоту, настройте комиссии и себестоимость Stars." />}</Panel>{preview && <OperationConfirm operation={preview} onClose={() => setPreview(null)} act={act} busy={busy} />}</>;
}

export function Competitors({ act, busy }: Actions) {
  const data = useData("/competitors"), lots = useData("/lots");
  const [form, setForm] = useState<any>(null);
  const selectedLot = lots.data?.items?.find((l: Row) => l.id === form?.lot_id);
  return <><div className="section-toolbar"><span className="section-caption">{data.data?.items?.length || 0} предложений в мониторинге</span><div className="button-group"><Button secondary disabled={busy} onClick={() => act(() => task("/competitors/refresh"), "Цены конкурентов проверены")}><RefreshCw size={15} />Проверить цены</Button><Button onClick={() => setForm({ url: "", lot_id: "", confirmed: false, enabled: true, note: "" })}><Plus size={15} />Добавить конкурента</Button></div></div><Panel title="Конкурентные предложения" subtitle="Сравниваются только подтверждённые коллекции и модели">{data.data?.items?.length ? <div className="table-scroll"><table><thead><tr><th>Объявление конкурента</th><th>Ваш лот</th><th>Цена</th><th>Сопоставление</th><th>Проверка</th><th /></tr></thead><tbody>{data.data.items.map((c: Row) => <tr key={c.id}><td><strong>{c.title || "Ожидает проверки"}</strong><small>{c.note}</small>{c.last_error && <small className="red-text">{c.last_error}</small>}</td><td>{lots.data?.items?.find((l: Row) => l.id === c.lot_id)?.title || c.lot_id.slice(-12)}</td><td>{money(c.price)}<small>{c.enabled ? "Мониторинг включён" : "Выключен"}</small></td><td><Badge tone={c.confirmed || c.auto_matched ? "green" : "amber"}>{c.confirmed ? "Подтверждено вами" : c.auto_matched ? "Модель совпадает" : "Нужно подтверждение"}</Badge></td><td>{date(c.fetched_at)}</td><td><div className="row-actions"><External href={c.url} /><button className="icon-button" aria-label="Изменить конкурента" onClick={() => setForm({ id: c.id, url: c.url, lot_id: c.lot_id, confirmed: c.confirmed, enabled: c.enabled, note: c.note || "" })}><Edit3 size={16} /></button><button className="icon-button" aria-label="Удалить конкурента" disabled={busy} onClick={() => act(() => api(`/competitors/${c.id}`, "DELETE"), "Конкурент удалён")}><Trash2 size={16} /></button></div></td></tr>)}</tbody></table></div> : <Empty text="Добавьте конкурента" detail="Вставьте ссылку и выберите связанный лот." />}</Panel>{form && <Dialog title={form.id ? "Настройки конкурента" : "Добавить конкурента"} onClose={() => setForm(null)} footer={<Button disabled={busy || !selectedLot?.pair_id || !form.url} onClick={() => act(async () => { const body = { url: form.url, lot_id: form.lot_id, pair_id: selectedLot.pair_id, confirmed: form.confirmed, enabled: form.enabled, note: form.note }; await api(form.id ? `/competitors/${form.id}` : "/competitors", form.id ? "PUT" : "POST", body); setForm(null); })}>Сохранить</Button>}><Field label="Ссылка на Playerok"><input type="url" value={form.url} onChange={e => setForm({ ...form, url: e.target.value })} /></Field><Field label="Ваш лот"><select value={form.lot_id} onChange={e => setForm({ ...form, lot_id: e.target.value, confirmed: false })}><option value="">Выберите лот с привязанной моделью</option>{options((lots.data?.items || []).filter((l: Row) => l.pair_id), "title")}</select></Field>{selectedLot?.pair && <div className="pair-preview"><Gift size={20} />{selectedLot.pair.collection} — {selectedLot.pair.model}</div>}<Toggle label="Коллекция и модель конкурента совпадают" description="Подтвердите после проверки объявления. Отличия условий укажите ниже." checked={form.confirmed} onChange={v => setForm({ ...form, confirmed: v })} /><Toggle label="Мониторинг включён" checked={form.enabled} onChange={v => setForm({ ...form, enabled: v })} /><Field label="Особенности предложения"><textarea rows={3} value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} placeholder="Например, у конкурента есть выбор фона" /></Field></Dialog>}</>;
}

export function Promotions({ act, busy }: Actions) {
  const data = useData("/promotions"), lots = useData("/lots");
  const [selectedIds, setSelectedIds] = useState<string[]>([]), [interval, setInterval] = useState("60"), [maxCost, setMaxCost] = useState("0"), [enabled, setEnabled] = useState(false), [preview, setPreview] = useState<Row | null>(null);
  const [deleting, setDeleting] = useState<Row | null>(null);
  const selected = selectedIds.length === 1 ? selectedIds[0] : "";
  const [resolveOp, setResolveOp] = useState<Row | null>(null);
  const active = (lots.data?.items || []).filter((l: Row) => l.status === "APPROVED" && !l.missing);
  return <><div className="two-columns"><Panel title="Поднятие активного лота" subtitle="Премиум оплачивается с баланса Playerok"><div className="form-pad"><fieldset className="schedule-picker"><legend>Объявления · выбрано {selectedIds.length}</legend><div className="schedule-picker-actions"><button type="button" className="text-link" onClick={() => setSelectedIds(active.map((l: Row) => l.id))}>Выбрать все</button><button type="button" className="text-link" disabled={!selectedIds.length} onClick={() => setSelectedIds([])}>Снять выбор</button></div><div className="schedule-picker-list">{active.map((l: Row) => <label key={l.id}><input type="checkbox" aria-label={`Расписание для ${l.title}`} checked={selectedIds.includes(l.id)} onChange={e => { const ids = e.target.checked ? [...selectedIds, l.id] : selectedIds.filter(id => id !== l.id); setSelectedIds(ids); if (ids.length === 1) { const saved = data.data?.items?.find((r: Row) => r.id === ids[0]); if (saved) { setEnabled(!!saved.enabled); setInterval(String((saved.interval || 3600) / 60)); setMaxCost(saved.max_cost_rub || "0"); } } }} /><span>{l.title}</span></label>)}{!active.length && <p className="muted">Активных лотов пока нет.</p>}</div></fieldset><div className="form-grid"><Field label="Интервал, минут"><input type="number" min={1} value={interval} onChange={e => setInterval(e.target.value)} /></Field><Field label="Лимит одной покупки, ₽" help="0 — без ограничений."><input type="number" min={0} value={maxCost} onChange={e => setMaxCost(e.target.value)} /></Field></div><Toggle label="Поднимать по расписанию" checked={enabled} onChange={setEnabled} description="Требуется включить премиум в настройках. Нулевые лимиты означают отсутствие ограничений." /><div className="button-group"><Button secondary disabled={busy || !selectedIds.length} onClick={() => act(() => api("/promotions/schedules/bulk", "PUT", { item_ids: selectedIds, enabled, interval: Number(interval) * 60, max_cost_rub: maxCost }), `Расписание сохранено для ${selectedIds.length} лотов`)}>Сохранить для выбранных · {selectedIds.length}</Button><Button disabled={busy || !selected} onClick={() => act(async () => setPreview(await task(`/promotions/${selected}/preview`)), "Стоимость поднятия получена")}><ArrowUp size={16} />Узнать стоимость</Button></div><p className="muted footnote" style={{ marginTop: 12 }}>Общие параметры сохраняются для всех выбранных лотов. Чтобы узнать стоимость поднятия, выберите один лот.</p></div></Panel><Panel title="Контроль расходов" subtitle="Каждая покупка проходит отдельную проверку"><div className="feature-list"><div><span>01</span><p>Стоимость и тариф запрашиваются для выбранного объявления.</p></div><div><span>02</span><p>Перед покупкой проверяются баланс и оставшийся дневной бюджет.</p></div><div><span>03</span><p>При неопределённом результате запрос не повторяется без сверки.</p></div></div><div className="panel-note"><ShieldCheck size={18} />Оплата требует разрешения на поднятия и доступного бюджета</div></Panel></div><Panel title="Расписания">{data.data?.items?.length ? <div className="table-scroll"><table><thead><tr><th>Объявление</th><th>Интервал</th><th>Лимит</th><th>Последнее поднятие</th><th>Следующее</th><th>Состояние</th><th>Действия</th></tr></thead><tbody>{data.data.items.map((s: Row) => <tr key={s.id}><td><strong>{lots.data?.items?.find((l: Row) => l.id === s.id)?.title || s.id.slice(-12)}</strong></td><td>{Math.round((s.interval || 3600) / 60)} мин</td><td>{Number(s.max_cost_rub) === 0 ? "Без ограничений" : money(s.max_cost_rub)}</td><td>{date(s.last_at)}</td><td>{s.enabled ? date(s.next_at) : "—"}</td><td><Badge tone={s.enabled ? "green" : "neutral"}>{s.enabled ? "Включено" : "Выключено"}</Badge></td><td><button className="icon-button" title="Удалить расписание" aria-label={`Удалить расписание ${lots.data?.items?.find((l: Row) => l.id === s.id)?.title || s.id}`} disabled={busy} onClick={() => setDeleting(s)}><Trash2 size={17} /></button></td></tr>)}</tbody></table></div> : <Empty text="Расписаний пока нет" />}</Panel><Panel title="История поднятий">{data.data?.operations?.length ? <div className="table-scroll"><table><thead><tr><th>Время</th><th>Лот</th><th>Стоимость</th><th>Результат</th><th /></tr></thead><tbody>{data.data.operations.map((o: Row) => <tr key={o.id}><td>{date(o.updated_at)}</td><td>{lots.data?.items?.find((l: Row) => l.id === o.payload?.lot_id)?.title || o.payload?.lot_id?.slice(-12)}</td><td>{money(o.expected?.cost_rub)}</td><td><State value={o.state} />{o.error && <small className="red-text">{o.error}</small>}</td><td>{o.state === "UNKNOWN" && <div className="button-group"><Button secondary disabled={busy} onClick={() => act(() => task(`/operations/${o.id}/reconcile`), "Сверка завершена")}>Сверить</Button><Button secondary onClick={() => setResolveOp(o)}>Зафиксировать проверку</Button></div>}</td></tr>)}</tbody></table></div> : <Empty text="Платных поднятий ещё не было" detail="Предварительный расчёт не списывает средства." />}</Panel>{deleting && <Dialog title="Удалить расписание?" busy={busy} onClose={() => setDeleting(null)} footer={<><Button secondary disabled={busy} onClick={() => setDeleting(null)}>Отмена</Button><Button danger disabled={busy} onClick={() => act(async () => { await api(`/promotions/${deleting.id}/schedule`, "DELETE"); if (selectedIds.includes(deleting.id)) setEnabled(false); setDeleting(null); }, "Расписание удалено")}>Удалить расписание</Button></>}><p>{lots.data?.items?.find((l: Row) => l.id === deleting.id)?.title || deleting.id}</p><p className="muted">Будущие поднятия по этому расписанию прекращаются. История операций и расходов сохранится. Уже отправленный платёж может завершиться.</p></Dialog>}{resolveOp && <ResolutionDialog operation={resolveOp} onClose={() => setResolveOp(null)} act={act} busy={busy} />}{preview && <OperationConfirm operation={preview} onClose={() => setPreview(null)} act={act} busy={busy} />}</>;
}

export function Orders({ act, busy }: Actions) {
  const data = useData("/orders");
  const [filter, setFilter] = useState("all"), [detail, setDetail] = useState<Row | null>(null), [reason, setReason] = useState("");
  const records = (data.data?.items || []).filter((o: Row) => filter === "all" || o.stage === filter);
  const retryStages = ["MANUAL", "DISCOVERED", "AWAITING_ENABLE", "WAITING_DATA", "CHECK_PRICE", "PURCHASED", "WITHDRAWN", "TRANSFERRED"];
  const canRetry = detail && (detail.retry_allowed ?? (retryStages.includes(detail.stage) && detail.source !== "legacy" && !detail.cancel_requested
    && !(data.data?.operations || []).some((o: Row) => o.order_id === detail.id && ["QUEUED", "UNKNOWN", "SUBMITTED", "BROWSER_WAIT"].includes(o.state))));
  return <><div className="section-toolbar"><select value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Все заказы</option><option value="MANUAL">Ручная обработка</option><option value="AWAITING_ENABLE">Выдача выключена</option><option value="COMPLETE">Завершённые</option><option value="HISTORICAL">Исторические</option></select><Button secondary disabled={busy} onClick={() => act(() => task("/orders/sync"), "Заказы синхронизированы")}><RefreshCw size={15} />Проверить заказы</Button></div><Notice>Закупка MRKT и автовыдача применяются только к Telegram NFT с привязанной моделью и включёнными разрешениями. Обычные товары обрабатываются вручную. Импортированные заказы не повторяются.</Notice><Panel title="Заказы Playerok">{records.length ? <div className="table-scroll"><table><thead><tr><th>Заказ</th><th>Получатель</th><th>Оплачено</th><th>Этап</th><th>Обновление</th><th /></tr></thead><tbody>{records.map((o: Row) => <tr key={o.id}><td><strong>{o.title || "Заказ Playerok"}</strong><small>{o.id.slice(-12)}</small></td><td>{o.recipient ? "@" + o.recipient : <span className="muted">Не определён</span>}</td><td>{money(o.sale_rub)}</td><td><State value={o.stage} /></td><td>{date(o.updated_at)}</td><td><Button secondary onClick={() => { setDetail(o); setReason(o.reason || ""); }}>Подробнее</Button></td></tr>)}</tbody></table></div> : <Empty text="Нет заказов по этому фильтру" />}</Panel>{detail && <Dialog title="Карточка заказа" onClose={() => setDetail(null)} busy={busy} footer={<><Button disabled={busy || !canRetry} onClick={() => act(async () => {
    await task(`/orders/${detail.id}/process`);
    const refreshed = await data.mutate();
    const order = refreshed?.items?.find((o: Row) => o.id === detail.id);
    if (order) { setDetail(order); setReason(order.reason || ""); }
  }, "Заказ запущен без ограничения целевой прибыли")}><RefreshCw size={15} />Повторить</Button><Button secondary disabled={busy} onClick={() => setDetail(null)}>Закрыть</Button></>}><div className="order-title"><strong>{detail.title}</strong><small>{detail.id}</small><State value={detail.stage} /></div><div className="summary-grid"><div><small>Получатель</small><strong>{detail.recipient ? "@" + detail.recipient : "—"}</strong></div><div><small>Оплачено</small><strong>{money(detail.sale_rub)}</strong></div><div><small>NFT</small><strong>{detail.gift_slug || "Не приобретён"}</strong></div><div><small>Источник</small><strong>{detail.source === "legacy" ? "Прототип" : "Playerok"}</strong></div></div>{detail.reason && <Notice>{detail.reason}</Notice>}{canRetry && <p className="muted">«Повторить» запускает заказ даже при прибыли ниже заданной. Лимиты расходов и проверки оплаты сохраняются.</p>}{detail.retry_reason && <p className="muted">Повтор недоступен: {detail.retry_reason}</p>}<Field label="Комментарий ручной обработки"><textarea rows={3} value={reason} onChange={e => setReason(e.target.value)} /></Field><div className="button-group"><Button secondary disabled={busy || !reason.trim()} onClick={() => act(async () => { await api(`/orders/${detail.id}`, "PATCH", { stage: "MANUAL", reason }); setDetail(null); }, "Комментарий сохранён")}>Оставить на ручной обработке</Button><Button danger disabled={busy || !reason.trim() || detail.stage === "COMPLETE"} onClick={() => act(async () => { await api(`/orders/${detail.id}`, "PATCH", { stage: "CANCELLED", reason }); setDetail(null); }, "Автоисполнение заказа отменено")}>Отменить автоисполнение</Button></div><div className="mini-timeline">{(data.data?.operations || []).filter((o: Row) => o.order_id === detail.id).map((o: Row) => <div key={o.id}><State value={o.state} /><span>{o.action}</span><small>{o.error}</small></div>)}</div></Dialog>}</>;
}

export function Finance() {
  const [period, setPeriod] = useState("all"), [lotId, setLotId] = useState(""), [pairId, setPairId] = useState(""), [from, setFrom] = useState(""), [to, setTo] = useState("");
  const lots = useData("/lots"), pairs = useData("/gift-pairs");
  const params = new URLSearchParams();
  if (lotId) params.set("lot_id", lotId); if (pairId) params.set("pair_id", pairId);
  if (period === "custom") { if (from) params.set("start", String(new Date(from + "T00:00:00+03:00").getTime() / 1000)); if (to) params.set("end", String(new Date(to + "T23:59:59+03:00").getTime() / 1000)); }
  else if (period !== "all") { const localDay = new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Volgograd" }); const start = new Date(localDay + "T00:00:00+03:00").getTime() / 1000 - (Number(period) - 1) * 86400; params.set("start", String(start)); }
  const data = useData("/finance?" + params.toString()), totals = data.data?.totals;
  const labels: Record<string, string> = { revenue: "Выручка", purchase: "Закупка NFT", transfer: "Передача", promotion: "Премиум", fees: "Комиссии" };
  const grouped: Record<string, number> = {};
  for (const e of data.data?.items || []) { const day = new Date(e.updated_at * 1000).toLocaleDateString("sv-SE", { timeZone: "Europe/Volgograd" }); grouped[day] = (grouped[day] || 0) + (e.type === "revenue" ? 1 : -1) * Number(e.amount_rub); }
  return <><PlayerokBalance /><div className="section-toolbar wrap"><div className="button-group"><select aria-label="Период" value={period} onChange={e => setPeriod(e.target.value)}><option value="all">Всё время</option><option value="1">Сегодня</option><option value="7">Неделя</option><option value="30">Месяц</option><option value="custom">Свой период</option></select><select aria-label="Лот" value={lotId} onChange={e => setLotId(e.target.value)}><option value="">Все лоты</option>{options(lots.data?.items || [], "title")}</select><select aria-label="Пара" value={pairId} onChange={e => setPairId(e.target.value)}><option value="">Все модели</option>{(pairs.data?.items || []).map((p: Row) => <option key={p.id} value={p.id}>{p.collection} — {p.model}</option>)}</select></div>{period === "custom" && <div className="button-group"><input aria-label="С даты" type="date" value={from} onChange={e => setFrom(e.target.value)} /><input aria-label="По дату" type="date" value={to} onChange={e => setTo(e.target.value)} /></div>}</div><div className="metrics"><Metric title="Выручка" value={money(totals?.revenue)} icon={CircleDollarSign} detail="Подтверждённые продажи" accent /><Metric title="Закупка NFT" value={money(totals?.purchase)} icon={Gift} detail="Фактические расходы" /><Metric title="Комиссии и выдача" value={totals ? money(Number(totals.fees) + Number(totals.transfer) + Number(totals.promotion)) : "—"} icon={ReceiptText} detail="Включая премиум" /><Metric title="Чистая прибыль" value={money(data.data?.profit_rub)} icon={TrendingUp} detail="Прогнозы не включены" /></div><Panel title="Динамика результата" subtitle="Фактический финансовый результат по дням"><div className="form-pad"><Sparkline values={Object.keys(grouped).sort().map(day => grouped[day])} /></div></Panel><Panel title="История финансовых операций" subtitle="Исторические расходы без подтверждённых данных не восстанавливаются предположениями">{data.data?.items?.length ? <div className="table-scroll"><table><thead><tr><th>Время</th><th>Операция</th><th>Лот</th><th>Сумма</th><th>Заказ</th></tr></thead><tbody>{data.data.items.map((e: Row) => <tr key={e.id}><td>{date(e.updated_at)}</td><td>{labels[e.type] || e.type}</td><td>{lots.data?.items?.find((l: Row) => l.id === e.lot_id)?.title || "—"}</td><td className={e.type === "revenue" ? "green-text" : ""}>{e.type === "revenue" ? "+" : "−"}{money(e.amount_rub)}</td><td>{e.order_id?.slice(-12) || "—"}</td></tr>)}</tbody></table></div> : <Empty text="Финансовых операций пока нет" detail="Здесь будут подтверждённые продажи и расходы нового проекта." />}</Panel><Panel title="Прибыль по лотам">{data.data?.by_lot?.length ? <div className="table-scroll"><table><thead><tr><th>Лот</th><th>Результат</th></tr></thead><tbody>{data.data.by_lot.map((l: any) => <tr key={l.lot_id}><td>{lots.data?.items?.find((r: Row) => r.id === l.lot_id)?.title || l.lot_id}</td><td>{money(l.profit_rub)}</td></tr>)}</tbody></table></div> : <div className="panel-note">Появится после первых подтверждённых операций.</div>}</Panel></>;
}

export function Events() {
  const [search, setSearch] = useState(""), [level, setLevel] = useState("");
  const data = useData(`/events?q=${encodeURIComponent(search)}&level=${level}`);
  return <Panel title="Журнал событий" subtitle="Все важные действия сохраняются локально"><div className="table-toolbar"><label className="search-box"><Search size={16} /><input placeholder="Поиск по действию, лоту или заказу" value={search} onChange={e => setSearch(e.target.value)} /></label><select value={level} onChange={e => setLevel(e.target.value)}><option value="">Все события</option><option value="ERROR">Ошибки</option><option value="INFO">Информация</option></select></div><ErrorNotice error={data.error} cached={!!data.data} />{data.data?.items?.length ? <div className="events-list full">{data.data.items.map((e: Row) => <div className="event-item" key={e.id}><span className={`event-symbol ${e.level === "ERROR" ? "error" : ""}`}>{e.level === "ERROR" ? "!" : <Check size={13} />}</span><div><strong>{e.title}</strong><small>{e.detail}</small>{e.lot_id && <small>Лот: {e.lot_id}</small>}</div><time>{date(e.legacy_date || e.updated_at)}</time></div>)}</div> : <Empty text="События не найдены" />}</Panel>;
}

export function Settings({ act, busy }: Actions) {
  const data = useData("/settings"), automation = useData("/automation");
  const [changes, setChanges] = useState<Record<string, unknown>>({});
  const draft = data.data ? { ...data.data, ...changes } : null;
  const update = (key: string, value: unknown) => setChanges(current => ({ ...current, [key]: value }));
  const transportSaved = () => setChanges(current => {
    const next = { ...current };
    delete next.delivery_tested;
    return next;
  });
  return <><div className="section-toolbar"><span className="section-caption">Торговые настройки сохраняются этой кнопкой</span><Button disabled={!draft || busy || !Object.keys(changes).length} onClick={() => act(async () => {
    const saved = await api("/settings", "PATCH", changes);
    await data.mutate(saved, { revalidate: false });
    setChanges({});
  }, "Настройки сохранены")}>Сохранить настройки</Button></div><ConnectionSetup act={act} busy={busy} /><ChromeDelivery act={act} busy={busy} onTransportSaved={transportSaved} />{draft && <BuyerMessageTemplates values={draft} update={update} busy={busy} />}{draft && <><div className="two-columns"><Panel title="Режим работы" subtitle="Разрешения проверяются перед каждым внешним изменением"><div className="form-pad"><Toggle label="Аварийная остановка" checked={draft.emergency_stop} onChange={v => update("emergency_stop", v)} description="Останавливает новые торговые действия. Уже отправленные запросы требуют сверки." /><Toggle label="Автоматическое изменение цен" checked={draft.repricing_enabled} onChange={v => update("repricing_enabled", v)} /><Toggle label="Платные поднятия" checked={draft.promotions_enabled} onChange={v => update("promotions_enabled", v)} /><Toggle label="Покупка NFT на MRKT" checked={draft.purchases_enabled} onChange={v => update("purchases_enabled", v)} /><Toggle label="Передача NFT покупателям" checked={draft.transfers_enabled} onChange={v => update("transfers_enabled", v)} /><Toggle label="Выдача отдельно протестирована мной" checked={draft.delivery_tested} onChange={v => update("delivery_tested", v)} description="Подтверждение владельца после сквозного теста. Одна полученная форма оплаты не подтверждает успешную передачу." /><Toggle label="Telegram-уведомления и команды" checked={draft.notifications_enabled} onChange={v => update("notifications_enabled", v)} description="Сначала остановите старый проект. Два экземпляра одного бота конфликтуют." /></div></Panel><Panel title="Лимиты и себестоимость" subtitle="0 — без ограничений. Разрешения на расходы включаются отдельно."><div className="form-pad"><div className="form-grid"><Field label="Стоимость одного Star, ₽"><input type="number" step="0.0001" min={0} placeholder="Не задана" value={draft.stars_rub ?? ""} onChange={e => update("stars_rub", e.target.value === "" ? null : e.target.value)} /></Field><Field label="Резерв Stars на передачу"><input type="number" min={0} value={draft.transfer_stars_reserve} onChange={e => update("transfer_stars_reserve", Number(e.target.value))} /></Field><Field label="Закупка на заказ, ₽" help="0 — без ограничений."><input type="number" min={0} value={draft.purchase_limit_rub} onChange={e => update("purchase_limit_rub", e.target.value)} /></Field><Field label="Закупки за сутки, ₽" help="0 — без ограничений."><input type="number" min={0} value={draft.daily_purchase_limit_rub} onChange={e => update("daily_purchase_limit_rub", e.target.value)} /></Field><Field label="Премиум за сутки, ₽" help="0 — без ограничений."><input type="number" min={0} value={draft.daily_promotion_limit_rub} onChange={e => update("daily_promotion_limit_rub", e.target.value)} /></Field></div><Notice>При отсутствии модели система уведомит и остановит исполнение заказа. Активное объявление останется на площадке.</Notice></div></Panel></div><Panel title="Частота проверок и шаблон"><div className="form-pad"><div className="form-grid"><Field label="Цены MRKT, секунд"><input type="number" min={60} value={draft.quote_interval} onChange={e => update("quote_interval", Number(e.target.value))} /></Field><Field label="Цены конкурентов, секунд"><input type="number" min={60} value={draft.competitor_interval} onChange={e => update("competitor_interval", Number(e.target.value))} /></Field><Field label="Максимальный возраст цены MRKT, секунд"><input type="number" min={60} value={draft.quote_max_age} onChange={e => update("quote_max_age", Number(e.target.value))} /></Field></div><Field label="Шаблон описания новых лотов"><textarea rows={8} value={draft.description_template} onChange={e => update("description_template", e.target.value)} /></Field></div></Panel></>}<UpdateSettings /><AdminPassword act={act} busy={busy} /><Panel title="Фоновые задачи и резервные копии" subtitle="Работают независимо от открытого браузера" action={<Button secondary disabled={busy} onClick={() => act(() => task("/automation/backup"), "Резервная копия создана")}><Download size={15} />Создать копию</Button>}><div className="panel-note"><State value={automation.data?.worker?.status || "NOT_CHECKED"} /><span>Последний сигнал: {date(automation.data?.worker?.heartbeat)}</span></div><div className="table-scroll"><table><thead><tr><th>Задание</th><th>Состояние</th><th>Время</th><th>Ошибка</th></tr></thead><tbody>{(automation.data?.tasks || []).slice(0, 12).map((t: Row) => <tr key={t.id}><td>{({ sync_lots: "Синхронизация лотов", check: "Проверка подключений", check_updates: "Проверка обновлений", fx: "Курс TON", orders: "Проверка заказов", quotes: "Котировки MRKT", competitors: "Мониторинг конкурентов", reprice: "Расчёт цен", bot: "Telegram-бот", backup: "Резервная копия", promotions: "Расписания премиума" } as Record<string, string>)[t.kind] || t.kind}</td><td><State value={t.state} /></td><td>{date(t.due)}</td><td><span className="muted">{t.error || "—"}</span></td></tr>)}</tbody></table></div></Panel></>;
}
